import type { ComponentPropsWithoutRef } from 'react'

export interface IconProps
  extends Omit<ComponentPropsWithoutRef<'svg'>, 'children' | 'viewBox'> {
  size?: number | string
}

interface IconGlyphProps extends IconProps {
  path: string
  source: string
  viewBox: string
}

function IconGlyph({
  path,
  size = 16,
  source,
  viewBox,
  ...props
}: IconGlyphProps) {
  return (
    <svg
      aria-hidden="true"
      data-icon={source}
      height={size}
      viewBox={viewBox}
      width={size}
      {...props}
    >
      <path
        clipRule="evenodd"
        d={path}
        fill="currentColor"
        fillOpacity="0.9"
        fillRule="evenodd"
      />
    </svg>
  )
}

